  "plans.mobilePriceNote": "Yalnızca mobil plan, amaçlanan ABD taban fiyatıyla aylık $4.99'dır. App Store veya Google Play, satın almadan önce gerçek yerel abonelik fiyatını ve geçerli vergileri gösterir. Ürün, site ve personel izinleri, web sitesi kademelerinden ayrı olarak lansmanda belirlenir.",
  "plans.planChangeNote": "Bir web sitesi plan değişikliği, faturalandırma sağlayıcısı tarafından onaylanmalıdır. Yeni fiyat, yürürlük tarihi ve herhangi bir orantılı ücretlendirme, değişiklik yetkilendirilmeden önce açıklanacaktır. Bir yükseltme ikinci bir abonelik oluşturmamalıdır.",
  "plans.providerNote": "Fiyatlar, ücretler ve denemeler, abone olduğunuz sağlayıcı tarafından gerçekleştirilir — App Store, Google Play, web sitesi veya Shopify — asla bu sayfa tarafından değil.",
