  "upgrade.trialHistoryNote": "Essentials için ödeme yapıyorsanız ve Business'a geçerseniz, aynı müşteri hesabını ve deneme geçmişini korursunuz. Business ek bir yedi günlük deneme içermez. Orijinal denemeniz hâlâ devam ederken yükseltirseniz, orijinal bitiş tarihi sıfırlanmaz.",
  "upgrade.providerConfirmNote": "Plan değişiklikleri, faturalandırma sağlayıcısından onay gerektirir. Herhangi bir fiyat farkı, orantılı ücretlendirme ve yürürlük tarihi, değişikliği onaylamadan önce gösterilmelidir. Bir yükseltme, ikinci bir eşzamanlı abonelik oluşturmamalıdır.",
  "upgrade.chargedThroughProviderNote": "Plan değişiklikleri, faturalandırma sağlayıcısı aracılığıyla ücretlendirilir. Aboneliğinizi bu sayfadan, mevcut planınızın altındaki Aboneliği İptal Et düğmesini kullanarak veya Ayarlar'dan iptal edebilirsiniz. İptal etmek, ücretli döneminizin sonunda gelecek yenilemeleri durdurur; erişiminizi asla birden sona erdirmez. Mevcut ücretsiz çalışma alanları, bu seçenekleri görüntülemekle ücretlendirilmez.",
  "billing.cancel.title": "Aboneliği iptal ediniz",
  "billing.cancel.description": "{plan} aboneliğinden çıkınız. İptal etmek, ücretli döneminizin sonunda gelecek yenilemeleri durdurur — erişiminizi asla birden sona erdirmez.",
