  "billing.cancel.graceEndsOn": "15 günlük ek süre {date} tarihinde sona erdikten sonra, hesabınız ve tüm bilgileri kalıcı olarak silinir ve kurtarılamaz.",
  "billing.cancel.doneNoEnd": "Ücretli döneminizin sonuna kadar tam erişimi korursunuz. Bundan sonra 15 günlük salt okunur bir ek süre geçerli olur. {wipeSentence}",
