  "materials.tookApart": "{location} konumunda {amount} × {name} parçalarına ayrıldı · {reference}. Parçalar rafa geri döndü; {remaining} kaldı.",
  "exports.eyebrow": "Veriler",
  "exports.title": "Dışa aktarımlar ve yedekler",
  "exports.subtitleStart": "İndirmeler her zaman şununla sınırlıdır",
  "exports.subtitleRest": ". Her dosya, işletme adı ve oluşturulma tarihiyle etiketlenir.",
  "exports.createBusinessFirst": "Önce bir işletme oluşturun — dışa aktarımlar uygulamaya değil, bir işletmeye aittir.",
  "exports.lockedTitle": "CSV ve Excel dışa aktarma bir Business özelliğidir",
  "exports.lockedDesc": "Çalışma alanınız Essentials planında. Business; CSV ve Excel dışa aktarımları, stok değerlemesi, sınırsız ürün ve personel, tedarikçiler, satın alma ve paketler ekler.",
  "exports.seeBusiness": "Business'ın neler içerdiğine bakın",
  "exports.whatTheseAre": "Bu dosyalar nedir",
  "exports.about1": "Her veri kümesi CSV veya gerçek bir Excel çalışma kitabı (.xlsx) olarak gelir — tam envanter çalışma kitabı yalnızca Excel biçimindedir ve her veri kümesi için ayrı bir sayfa içerir. CSV dosyaları Excel, Numbers, Google E-Tablolar ve çoğu stok uygulamasında açılır. UTF-8 metni, tırnak içine alınmış virgüller, notlardaki satır sonları ve kodlardaki baştaki sıfırlar korunur; formül gibi başlayan hücreler, bir elektronik tablonun bunları metin olarak açması için etkisizleştirilir.",
  "exports.about2": "Excel dosyalarında SKU'lar, UPC'ler, ISBN'ler ve barkodlar metin hücreleridir — asla bilimsel gösterimde değildir ve baştaki sıfırları asla kırpılmaz — sütun genişlikleri, başlık filtreleri ve para birimi veya miktar biçimleri uygulanmıştır. Tam envanter çalışma kitabı ürünleri, stok seviyelerini, konumları ve hareketleri ayrı sayfalarda tutar.",
  "exports.about3": "Çok büyük dışa aktarımlar veri kümesi başına 20.000 satırda durur — bu olduğunda dosya adı bunu belirtir (truncated-20000), böylece kısmi bir dosya asla tam gibi görünmez.",
  "exports.about4": "Yedek, verilerinizin bir anlık görüntüsüdür, tek tıklamayla geri yükleme değildir. Geri yükleme, önce inceleme gerektiren manuel bir iştir; bu yüzden dosyayı güvende tutun — uygulamadaki hiçbir şey, silinmiş bir işletmeyi henüz bu dosyadan yeniden oluşturamaz. Uygulama kodu ve Base44 platform yedekleri bu dosyalardan ayrı ele alınır.",
  "exports.about5": "Fotoğraflar ve ekler, kayıtlı bağlantıları olarak listelenir — görüntü dosyalarının kendileri indirmeye paketlenmez.",
  "exports.backupTitle": "Tam yedek",
  "exports.backupDesc": "Bu işletmenin ürünleri, konumları, stok seviyeleri, eksiksiz hareket defteri, tedarikçileri, satın almaları, siparişleri, iadeleri, sayımları ve listelemelerini — artı profil ayarlarını — içeren tek dosya. Onu kontrolünüzde olan bir yerde saklayın.",
  "exports.backupIncludes1": "Ürünler, kodlar, maliyetler ve notlar",
  "exports.backupIncludes2": "Konumlar ve konum başına miktarlar",
