  "import.createDesc": "henüz katalogda olmayan satırları ekler. Zaten kullanımda olan yinelenen SKU'lar ve barkodlar atlanır ve açılış stoğu, giriş olarak seçtiğiniz bir konuma düşebilir.",
  "import.updateTitle": "Mevcut ürünleri güncelle",
  "import.updateDesc": "her satırı SKU veya kayıt kimliğiyle eşleştirir ve eski değeri önerilen yeni değerin yanında gösterir. Boş hücreler, boşlukların temizlenmesini istemediğiniz sürece kayıtlı değeri olduğu gibi bırakır ve miktarlara asla dokunulmaz.",
