  "print.templateIsBusiness": "{label} bir Business özelliğidir",
  "print.supplierBlockedDesc": "Tedarikçi belgeleri Business planıyla gelir — tedarikçiler, satın alma ve satın alma siparişleri. Şu anda sahip olduğunuz her şey çalışmaya devam eder.",
  "print.seeBusiness": "Business'ın neler içerdiğine bakın",
  "print.nothingToPrint": "Henüz yazdırılacak bir şey yok",
  "print.pickOrderHint": "Belgeyi önizlemek için listeden bir satın alma siparişi seçin.",
  "print.pickCustomerOrderHint": "Belgeyi önizlemek için listeden bir müşteri siparişi seçin.",
  "print.pickReturnHint": "Belgeyi önizlemek için listeden kayıtlı bir iade seçin.",
  "print.chooseStyleHint": "Bir stil seçin, ardından listeden ürünleri seçin. Önizleme, yazıcıdan tam olarak ne çıkacağını gösterir.",
  "print.howToReach": "Yazıcınıza nasıl ulaşılır",
  "print.howIntro": "Bu uygulama, zaten sahip olduğunuz yazıcılara bağlanır — kendisi bir yazıcı değildir. Bir yazıcıya ulaşmanın dört yolu vardır ve etiketler her iki planda da bunların herhangi biriyle yazdırılır. Paketleme fişleri, satın alma siparişleri, tedarikçi belgeleri ve raporlar, bağlantı ne olursa olsun yalnızca Business'a özeldir.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "Bu sayfadan, masaüstü Chrome veya Edge'de ve Android Chrome'da: etiket yazıcınızı seçin, etiketler doğrudan ona gider. iOS Safari'de çalışmaz — iPhone'da Bluetooth yazdırma bunun yerine mobil uygulamayla gelir. Yalnızca Zebra ZPL veya Brother'ın kendi dilini konuşan bir yazıcı, bu sayfanın gönderdiği etiketleri anlamaz; bu, çalıştığı söylenmeden önce gerçek yazıcılarla test edilir.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Yazıcıyı mağazanızın Wi-Fi ağına kurun, ardından Yazdır düğmesini kullanın — bu bilgisayara kurulu yazıcı üzerinden, mağaza ağı yoluyla yazdırır. iPhone'da AirPrint yerleşiktir: aynı Wi-Fi'daki bir AirPrint yazıcısı yazdırma sayfasında kendiliğinden görünür; kablo da uygulama da gerekmez ve uygulamanın AirPrint'e özel koda ihtiyacı yoktur. Yazıcının AirPrint'i desteklemesi (çoğu yeni yazıcı destekler) ve telefon ile yazıcının aynı Wi-Fi'da olması gerekir.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Yazıcıyı bir Ethernet kablosuyla mağaza ağınıza bağlayın, bilgisayara kurun ve Yazdır düğmesiyle yazdırın. Ethernet bir masaüstü ve bilgisayar yoludur — iPhone'lar Ethernet kablosu kullanmaz.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Yazıcıyı kablosuyla bilgisayara takın ve Yazdır düğmesini kullanın — orada kurulu yazıcı üzerinden yazdırır. USB OTG kablosu olan bir Android telefonda, yukarıdaki USB düğmesi doğrudan yazıcıyla konuşur. iPhone'lar USB üzerinden doğrudan yazdıramaz — orada WebUSB yok — bu yüzden Wi-Fi / AirPrint kullanın veya mobil uygulamadan Bluetooth ile yazdırın.",
  "print.howCordsLead": "Kablolar iPhone'lara bir adım uzaktan da hizmet eder.",
  "print.howCordsBody": "Mağaza bilgisayarına takılı bir USB yazıcı veya ağa kablolu bağlı bir Ethernet yazıcı, iPhone'unuzda mağaza Wi-Fi'ı üzerinden görünür (AirPrint / paylaşımlı yazıcı) — kablolar yazıcıyı ağa sağlamca koyar, telefon ona kablosuz ulaşır.",
  "print.howOfflineLead": "İnternet kesilirse,",
  "print.howOfflineBody": "bu sayfada zaten bulunan etiketler ve belgeler yine de yazdırılır — Yazdır düğmesi, Etiketler PDF'si, Bluetooth ve USB bağlantı gerektirmez. İnternet gerektiren şey, sayfayı ve ürünlerini en başta yüklemektir. Tam çevrimdışı mod (hiç bağlantı olmadan uygulamada çalışmak) ayrı, daha büyük bir yapıdır ve burada iddia edilmez.",
