  "settings.cancelTerms.graceTitle": "Ödenen döneminiz sona erdikten sonra — 15 günlük ek süre, ardından silme:",
  "settings.cancelTerms.intro": "Bunlar, ücretli Luminous StockHaven abonelikleri için geçerli koşullardır. Web sitesi abonelik faturalandırması Stripe üzerinden yapılır. Aboneliğinizi, aşağıdaki Aboneliği İptal Et düğmesini kullanarak istediğiniz zaman kendiniz iptal edebilirsiniz — personel onayı gerekmez. İptal ve iade istekleri, resmi müşteri destek iletişim adresi theluminousbookshop@outlook.com üzerinden de ele alınabilir.",
  "settings.cancelTerms.noApprovalBody": "Aboneliğinizi istediğiniz zaman kendiniz iptal edebilirsiniz. Personel onayı gerekmez. Gelecekteki yenilemeler yalnızca faturalandırma sağlayıcısı iptali onayladıktan sonra durur.",
  "settings.cancelTerms.noApprovalTitle": "Onay olmadan iptal:",
  "settings.cancelTerms.paymentBody": "Ücretli denemelerde, yedi günlük deneme, kaydolurken bir ödeme yöntemi gerektirir. İlgili deneme iptal son tarihine kadar iptal edilmezse, seçilen aylık plan, denemeden sonra otomatik olarak ücretlendirilir. Fiyat, ilk faturalandırma tarihi ve sağlayıcıya özgü iptal son tarihi, kayıt sırasında gösterilmelidir. Deneme faturalandırması Stripe üzerinden yapılır.",
  "settings.cancelTerms.paymentTitle": "Ödeme yöntemi ve otomatik yenileme:",
  "settings.cancelTerms.remainingBody": "Bir faturalandırma dönemi için zaten ödeme yaptıysanız, doğrulanan ödenmiş tarihe kadar erişimi sürdürebilirsiniz. Daha erken sonlandırma, uygun sağlayıcı onayı ve geçerli iade işlemlerini gerektirir. Ücretsiz deneme erişimi, sağlayıcı tarafından onaylanan deneme sonlandırma tarihine göre sona erer.",
  "settings.cancelTerms.remainingTitle": "Kalan erişim:",
  "settings.cancelTerms.storesBody": "Google Play veya Apple App Store üzerinden abone olursanız, aboneliğiniz o mağaza tarafından faturalandırılır ve yönetilir. Abone olmak için kullanılan aynı Google veya Apple hesabının abonelikler bölümünde doğrudan iptal etmeniz gerekebilir. Ayrı bir web sitesi aboneliğini iptal etmek, bu uygulamayı kaldırmak veya Luminous StockHaven hesap silme isteğinde bulunmak, mağaza tarafından faturalandırılan bir aboneliği otomatik olarak iptal etmez. Sizi kimin faturalandırdığını doğrulamak için satın alma makbuzunuzu kontrol edin.",
  "settings.cancelTerms.storesTitle": "Google Play ve Apple App Store abonelikleri (bir mağaza üzerinden abone olursanız):",
  "settings.cancelTerms.title": "İptal Hüküm ve Koşulları",
  "settings.cancelTerms.trialBody": "Yedi günlük deneme, uygun müşteri başına yalnızca bir kez kullanılabilir. Bir denemeyi veya aboneliği iptal etmek başka bir deneme hakkı vermez; geri dönen müşteriler ücretli bir abonelik seçmelidir.",
  "settings.cancelTerms.trialTitle": "Bir ücretsiz deneme:",
  "settings.canceled.endsOn": "Bu abonelik iptal edildi ve {date} tarihinde sona eriyor. O zamana kadar tam erişiminiz devam eder.",
  "settings.delete.checking": "Mevcut bir silme isteği kontrol ediliyor…",
  "settings.delete.description": "Luminous StockHaven oturum açma hesabınızın kaldırılmasını isteyin.",
  "settings.delete.dialogDescription": "Bu, hesap silme incelemesi isteğinde bulunur. Oturumunuzu veya envanterinizi hemen kaldırmaz ve hiçbir Stripe aboneliğini iptal etmez. İsteği göndermek istediğinizi onaylamak için {word} yazın.",
  "settings.delete.dialogTitle": "Hesap Silme İsteğinde Bulunun",
  "settings.delete.enterDelete": "Onaylamak için {word} girin",
  "settings.delete.exportFirst": "Kayıtlarınızı saklamanız gerekiyorsa önce envanterinizi dışa aktarın.",
  "settings.delete.intro": "Bir istek göndermek, hesabınızı, işletmelerinizi veya envanterinizi hemen silmez. İstekler, silme tamamlanmadan önce ayrı ayrı incelenir. Bu istek, bir Stripe aboneliğini iptal etmez veya gelecekteki faturalandırmayı durdurmaz; abonelik iptali, faturalandırma sağlayıcısı aracılığıyla ayrıca ele alınmalıdır.",
  "settings.delete.keepAccount": "Hesabı Koru",
  "settings.delete.noExport": "Essentials planında dışa aktarma yoktur — silme isteğinde bulunmadan önce ihtiyacınız olan her şeyi not edin.",
  "settings.delete.notDeleted": "Hesabınız ve verileriniz bu istekle silinmedi. Faturalandırma iptal edilmedi.",
