  "settings.pastDue.body": "Son ödemeniz gerçekleşmedi. Ödeme yönteminizi Yükselt sayfasından güncelleyin — Stripe kendi programına göre yeniden deneyecektir ve aboneliğiniz erken iptal edilmeyecektir. Ne yapacağınızdan emin değilseniz, theluminousbookshop@outlook.com adresinden destek ile iletişime geçin.",
