  "settings.trial.cancelKeeps": "Denemeniz sırasında iptal etmek, tam 7 gününüzü korur — erişim {date} tarihinde sona erer ve sizden ücret alınmaz.",
  "staff.access.noSeatBody": "Hesabınızın bu işletme için personel koltuğu yok, bu nedenle stoğu kapalı kalır. Sahibinden sizi Personel ve roller bölümünde eklemesini isteyin.",
  "staff.access.noSeatTitle": "Bu işletme oturumunuza açık değil",
  "staff.access.pendingBody": "Bu işletmede, etkinleştirilmemiş bir e-postanız için davet var. Sahibinden personel durumunuzu etkin olarak ayarlamasını isteyin. O zamana kadar burada hiçbir şey görünmez.",
  "staff.access.pendingTitle": "Davetiniz henüz etkin değil",
  "staff.access.signOut": "Çıkış yap",
  "staff.access.suspendedBody": "Bir yönetici, etkin işletme için bu personel hesabını askıya aldı. Sizden tekrar etkin olarak ayarlamalarını isteyin, ardından tekrar oturum açın.",
  "staff.access.suspendedTitle": "Erişiminiz duraklatıldı",
  "staff.addFirst": "İlk personel üyesini ekleyin",
  "staff.addMember": "Personel üyesi ekle",
  "staff.emptyBody": "Bir kişi ekleyin, ona bir rol ve onunla gelen izinleri verin; bu işletmede oturum açmak için e-posta ile davet edilir.",
  "staff.emptyTitle": "Henüz personel yok",
  "staff.eyebrow": "Ekip",
  "staff.how.p1": "Her üyenin bir rolü ve kendi izin listesi vardır, bu nedenle bir rolden başlayıp yeni bir rol oluşturmadan bir şeyi değiştirebilirsiniz. Bir rolü düzenlemek, zaten o rolde olan üyeleri yeniden yazmaz — rol varsayılanlarını yeniden uygulamak için bir üyeyi açın.",
  "staff.how.p2": "Özel roller bir Business özelliğidir: Essentials beş yerleşik rolü kullanır (Owner, Manager, Stock clerk, Sales clerk, Viewer).",
  "staff.how.p3": "Davetler e-posta ile gönderilir. Bir üye yalnızca kabul ettikten sonra oturum açabilir ve birini bu listeden çıkarmak, uygulama hesabını silmez.",
  "staff.how.p4": "Bir mağaza, bir kişinin atandığı konumdur. Kartında kaydedilir; neyi açabileceği hâlâ rolü ve izinleriyle belirlenir.",
  "staff.how.p5": "İzinler, her kişinin neyi açabileceğini belirler: rolü dışındaki menü öğeleri gizlenir ve engellenen bir adres, sayfa yerine “rolünüzde yok” bildirimi gösterir. Bir değişiklik, o kişi uygulamayı bir sonraki yükleyişinde uygulanır; bir üyeyi askıya almak onu tamamen kilitler.",
  "staff.how.p6": "Yöneticiler tüm verileri görebilir ve değiştirebilir, uygulama kullanıcılarını ve rollerini yönetebilir ve bir personel rolüyle asla sınırlanmaz. Personel kaydı olmayan biri — yeni bir işletmenin sahibi — tam erişimi korur.",
  "staff.howTitle": "Personel ve roller nasıl çalışır",
  "staff.limitBadgeLabel": "Personel",
  "staff.loading": "Personel yükleniyor…",
