  "auth.sameEmailNotice": "Uygulamamızı zaten Google Play veya App Store'dan aldınız mı? Mağazanızın ve envanterinizin sizinle gelmesi için burada aynı e-postayı — uygulamaya oturum açtığınız e-postayı — kullanınız. Farklı bir e-posta tamamen yeni, boş bir mağaza başlatır.",
