  "rewards.subtitle": "Bir ödülle teşekkür ediniz — bir indirim yüzdesi, bir hediye kartı veya anlattığınız herhangi bir şey.",
  "rewards.title": "Ödüller ve teşvikler",
  "rewards.value.giftCard": "{value} hediye kartı",
  "rewards.value.percentOff": "Mağazada %{percent} indirim",
