  "workforce.tab.rewards": "Ödüller",
  "training.lessons.mgr-give-rewards.step1": "İş Gücü'nü açınız ve Ödüller'e dokununuz. Ekip üyesini, sonra türü seçiniz: mağazada bir indirim yüzdesi, bir hediye kartı veya kendi sözlerinizle anlattığınız başka bir şey.",
  "training.lessons.mgr-give-rewards.step2": "Ödüle kısa bir ad ve isterseniz bir not veriniz. Kişi hemen bir zil alır ve ödül kendi koduyla Ödüllerim'de bekler.",
  "training.lessons.mgr-give-rewards.step3": "Tasarım gereği sınır: yalnızca PERSONELİ ödüllendirirsiniz. Kendinizi veya başka bir yöneticiyi ödüllendiremezsiniz — bir yöneticiyi ödüllendirmek sahibin kararıdır ve uygulama bunu açıkça reddeder.",
  "training.lessons.mgr-give-rewards.step4": "Kasada, ekip üyesinin size gösterdiği kodu yazınız ve kullanıldı olarak işaretleyiniz — her kod bir kez çalışır. Planlar değişirse verdiğiniz bir ödülü geçersiz kılabilirsiniz; sahibin hediyeleri geçersiz kılmak sahibe aittir.",
  "training.lessons.mgr-give-rewards.title": "Personelinize ödül vermek",
  "training.lessons.owner-give-rewards.step1": "Ödüller İş Gücü'nde, Ödüller sekmesinde yaşar ve yalnızca Business planındadır — Essentials'ta sekme kilitli bir kapı gösterir, böylece ekibiniz daha büyük planın ne tuttuğunu görebilir.",
  "training.lessons.owner-give-rewards.step2": "Ekipteki HERKESİ ödüllendirebilirsiniz — personel ve yöneticiler aynı şekilde. Kişiyi, sonra türü seçiniz: mağazada indirim yüzdesi (seçtiğiniz herhangi bir yüzde), herhangi bir yere bir hediye kartı veya kendi sözlerinizle anlattığınız herhangi bir teşvik.",
  "training.lessons.owner-give-rewards.step3": "Ödül kendi tek kullanımlık koduyla iner ve kişinin zilini çalar. Kodu kasada gösterirler; bir sahip veya yönetici kullanıldı olarak işaretlemek için yazar.",
  "training.lessons.owner-give-rewards.step4": "Basılı veya paylaşılan bir ödül fişi yalnızca SİZİN işletmenizin adını taşır — asla uygulamanın adını değil. Bu mağazanızın teşekkürüdür, bir reklam değil.",
  "training.lessons.owner-give-rewards.title": "Ödül vermek (Business planı)",
  "training.lessons.owner-rewards-oversight.step1": "Yöneticiniz de ödül verebilir — yalnızca personele. Uygulama, bir yöneticinin kendisini veya başka bir yöneticiyi ödüllendirmesini reddeder; bir yöneticiyi ödüllendirmek her zaman sizin kararınızdır.",
  "training.lessons.owner-rewards-oversight.step2": "İşletmedeki her ödülü Ödül geçmişinde görürsünüz: kim verdi, kim aldı ve hazır mı, kullanıldı mı veya geçersiz mi. Bir yönetici yalnızca verdiği ödülleri ve aldıklarını görür.",
  "training.lessons.owner-rewards-oversight.step3": "Yöneticinizin verdiği biri dahil herhangi bir ödülü geçersiz kılabilirsiniz. Bir yönetici kendi hediyelerini geçersiz kılabilir, ama asla sizinkileri değil.",
  "training.lessons.owner-rewards-oversight.step4": "Her kod tam olarak bir kez çalışır ve geçersiz kılınmış bir ödül asla kullanılamaz — geçmiş her zaman bir ödülün hangi şekilde bittiğini gösterir.",
  "training.lessons.owner-rewards-oversight.title": "Ödülleri denetlemek: yöneticinizin vermesi",
  "training.lessons.staff-your-rewards.step1": "Yöneticiniz veya sahip size bir ödül verdiğinde ziliniz çalar. Ödüllerim altında görmek için İş Gücü'nü açınız ve Ödüller'e dokununuz.",
  "training.lessons.staff-your-rewards.step2": "Her ödülün kendi kodu var. Onu kendinize saklayınız — kasada kodu gösteren kişi ödülü kullanan kişidir.",
  "training.lessons.staff-your-rewards.step3": "Kullanmak için satın alırken kodu gösteriniz. Kasadaki kişi onu yazar ve kullanıldı olarak işaretler — her kod tam olarak bir kez çalışır.",
  "training.lessons.staff-your-rewards.step4": "Ödüller bir Business planı ikramıdır. Mağazanız Business'ta değilse, Ödüller sekmesi bunun yerine kilitli bir kapı gösterir — bu plandır, bir hata değil.",
  "training.lessons.staff-your-rewards.title": "Ödülleriniz: kodunuzu bulmak ve kullanmak",
  "training.module.rewards": "Ödüller ve teşvikler",
